    stack = []

    for i, altura in enumerate(alturas + [0]):
        while stack and (i == len(alturas) or alturas[stack[-1]] >= altura):
            h = alturas[stack.pop()]
            w = i if not stack else i - stack[-1] - 1
            max_area = max(max_area, h * w)
        stack.append(i)

    return max_area

