def janela_deslizante_max(nums, k):
    if not nums or k <= 0 or k > len(nums):
        return []

    from collections import deque

    d = deque()
    maxima = []

    for i in range(len(nums)):
        while d and d[0] < i - k + 1:
            d.popleft()

        while d and nums[d[-1]] < nums[i]:
            d.pop()

        d.append(i)

        if i >= k - 1:
            maxima.append(nums[d[0]])

    return maxima

def resolve_expressao_simples(expr):
    tokens = []
    num = ''
    for c in expr:
        if c.isdigit():
            num += c
        else:
            if num:
                tokens.append(int(num))
                num = ''
            tokens.append(c)
    if num:
        tokens.append(int(num))

    i = 1
    while i < len(tokens):
        if tokens[i] == '*':
            tokens[i-1] *= tokens[i+1]
            del tokens[i:i+2]
        else:
            i += 1

    i = 1
    while i < len(tokens):
        if tokens[i] in ('+', '-'):
            op = tokens.pop(i)
            val = tokens.pop(i-1)
            if op == '+':
