def ratear_custo(pesos, total):
    if not pesos:
        return {name: 0 for name in pesos}

    peso_total = sum(pesos.values())

    if peso_total == 0 or any(weight < 0 for weight in pesos.values()) or total < 0:
        raise ValueError

    partes_inteiras = {}
    for nome, peso in pesos.items():
        if peso > 0:
            partes_inteiras[nome] = (total * peso) // peso_total

    sobra = total - sum(partes_inteiras.values())

    restos = [(nome, total * pesos[nome] % peso_total) for nome in pesos if pesos[nome] > 0]
    restos.sort(key=lambda x: (-x[1], x[0]))

    distribuicao_sobra = {}
    for i in range(sobra):
        distribuicao_sobra[restos[i][0]] = 1

    resultado = partes_inteiras.copy()
    resultado.update(distribuicao_sobra)

    return resultado

