def ler_plano(texto):
    def converte_tempo(tempo):
        minutos = 0
        for parte in tempo.split():
            if parte.endswith('h'):
                minutos += int(parte[:-1]) * 60
            elif parte.endswith('m'):
                minutos += int(parte[:-1])
        return minutos

    plano = {}
    tarefas = []
    linha_atual = ''
    ignore_linha = False

    for line in texto.splitlines():
        if ignore_linha:
            ignore_linha = False
            continue

        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if line.endswith('\\'):
            ignore_linha = True
            continue

        if line.startswith('tarefa:'):
            if linha_atual and linha_atual not in plano:
                raise ValueError(f"Nome de tarefa duplicado ou inválido: {linha_atual}")
            nome_tarefa = line.split(':', 1)[1].strip()
            plano[nome_tarefa] = {'duracao_min': 0, 'depende': []}
            tarefas.append(nome_tarefa)
        elif line in plano:
            if not line.startswith('duracao:'):
                raise ValueError(f"Chave inválida na linha de tarefa: {line}")
            valor = line.split(':', 1)[1].strip()
            if valor.endswith('\\'):
                ignore_linha = True
                continue
            plano[nome_tarefa]['duracao_min'] = converte_tempo(valor)
        elif line in plano:
            if not line.startswith('depende:'):
                raise ValueError(f"Chave inválida na linha de tarefa: {line}")
            valor = line.split(':', 1)[1].strip()
            if valor.endswith('\\'):
                ignore_linha = True
                continue
            dependes = [dep.strip() for dep in valor.split(',')]
            plano[nome_tarefa]['depende'] = dependes
        else:
            raise ValueError(f"Chave inválida ou ausente na linha de tarefa: {line}")

    if any(nome not in plano for nome in tarefas):
        raise ValueError("Alguma tarefa depende de uma tarefa não declarada.")

    return plano

