            k = int(k)
            if k < 0:
                raise ValueError("Movimento inválido")
            braço += sentido * k
            braço %= n

        elif comando == 'GIRA':
            sentido *= -1

        elif comando == 'PEGA':
            if item_mao is None and esteira[braço] is not None:
                pass
            else:
                item_mao = esteira.pop(braço)

        elif comando == 'SOLTA':
            if item_mao is None or esteira[braço] is not None:
                pass
            else:
                for i in range(n):
                    if esteira[i] is None:
                        esteira[i] = item_mao
                        break
                else:
                    raise ValueError("Nenhuma posição livre na esteira")

        else:
            raise ValueError("Comando inválido")

    return braço, item_mao, list(esteira)

