    stack = []
    max_area = 0
    i = 0

    while i < len(alturas):
        if not stack or alturas[stack[-1]] <= alturas[i]:
            stack.append(i)
            i += 1
        else:
            top_index = stack.pop()
            area = (i - stack[-1] - 1) * alturas[top_index] if stack else i * alturas[top_index]
            max_area = max(max_area, area)

    while stack:
        top_index = stack.pop()
        area = (i - stack[-1] - 1) * alturas[top_index] if stack else i * alturas[top_index]
        max_area = max(max_area, area)

