def calculadora_rpn(expressao):
    if not expressao.strip():
        raise ValueError("Expressao invalida ou vazia")

    operadores = {'+': lambda x, y: x + y,
                 '-': lambda x, y: x - y,
                 '*': lambda x, y: x * y,
                 '//': lambda x, y: x // y}

    pilha = []
    for token in expressao.split():
        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            pilha.append(int(token))
        elif token in operadores:
            if len(pilha) < 2:
                raise ValueError("Expressao invalida")
            y, x = pilha.pop(), pilha.pop()
            try:
                resultado = operadores[token](x, y)
            except ZeroDivisionError:
                raise ValueError("Divisao por zero")
            pilha.append(resultado)
        else:
            raise ValueError(f"Operador invalido: {token}")

    if len(pilha) != 1:
        raise ValueError("Expressao invalida")

    return pilha[0]

