def encontra_caminho_matriz(matriz):
    N = len(matriz)
    M = len(matriz[0])

    def dfs(linha, coluna, caminho):
        if linha == N-1 and coluna == M-1:
            return caminho + [(linha, coluna)]

        if linha >= N or coluna >= M or matriz[linha][coluna] == 1:
            return None

        # Marcar a celula atual como visitada
        matriz[linha][coluna] = 1

        # Recursao para baixo e para a direita
        caminho_below = dfs(linha + 1, coluna, caminho + [(linha, coluna)])
        if caminho_below is not None:
            return caminho_below

        caminho_right = dfs(linha, coluna + 1, caminho + [(linha, coluna)])
        if caminho_right is not None:
            return caminho_right

        # Se nenhum dos caminhos funcionar, desmarque a celula atual
        matriz[linha][coluna] = 0
        return None

    return dfs(0, 0, [])

