    soma_pesos = sum(pesos.values())
    if total == 0:
        return {nome: 0 for nome in pesos}

    distribuicao = {}
    resto = total

    for nome, peso in pesos.items():
        if peso > 0:
            parte_inteira = (total * peso) // soma_pesos
            distribuicao[nome] = parte_inteira
            resto -= parte_inteira * peso

    restantes = sorted([(resto % peso, nome) for nome, peso in pesos.items() if peso > 0], reverse=True)

    for resto_frac, nome in restantes:
