            resto -= 1

    return distribuicao

def simular_esteira(n, commands):
    positions = [None] * n
    arm_pos = 0
    hand_item = None
    direction = 1

    for cmd in commands:
        parts = cmd.split()
        if parts[0] == 'POE':
            x = int(parts[1])
            if positions[arm_pos] is not None:
                raise ValueError("Posicao ja possui item")
            positions[arm_pos] = x
        elif parts[0] == 'ANDA':
            k = int(parts[1])
            arm_pos = (arm_pos + direction * k) % n
        elif parts[0] == 'GIRA':
            direction *= -1
        elif parts[0] == 'PEGA':
            if hand_item is not None:
                raise ValueError("Mao ja possui item")
            if positions[arm_pos] is None:
                pass
            else:
                hand_item = positions[arm_pos]
                positions[arm_pos] = None
        elif parts[0] == 'SOLTA':
            if hand_item is None:
                raise ValueError("Mao nao possui item")
            for i in range(n):
                pos = (arm_pos + direction * i) % n
                if positions[pos] is not None:
                    positions[pos] = hand_item
                    hand_item = None
                    break
            else:
                raise ValueError("Nenhuma posicao livre na esteira")
        else:
            raise ValueError(f"Comando invalido: {cmd}")

    return (arm_pos, hand_item, positions)

