        return [(inicio, fim)] if inicio < fim else []

    # Ordena os intervalos por início
    ocupados.sort()

    # Remove sobreposicoes e cria uma lista de intervalos ocupados
    ocupados_ordenados = []
    for a, b in ocupados:
        if not ocupados_ordenados or ocupados_ordenados[-1][1] < a:
            ocupados_ordenados.append((a, b))

    # Encontra os intervalos livres entre [inicio, fim]
    livres = []
    atual = inicio

    for a, b in ocupados_ordenados:
        if atual < a:
            livres.append((atual, a))
        atual = b

    # Verifica se há espaço livre após o último intervalo ocupado
    if atual < fim:
        livres.append((atual, fim))

    # Filtra intervalos vazios
    result = [intervalo for intervalo in livres if intervalo[0] < intervalo[1]]

    return result

