    if op == '+':
        result += num
    elif op == '-':
        result -= num

    return result

def banco_simplificado(operacoes):
    contas = {}

    for operacao in operacoes:
        partes = operacao.split()
        comando = partes[0]

        if comando == 'CRIAR':
            conta = partes[1]
            if conta not in contas:
                contas[conta] = 0

        elif comando == 'DEPOSITAR':
            conta = partes[1]
            valor = int(partes[2])
            if conta in contas:
                contas[conta] += valor

        elif comando == 'SACAR':
            conta = partes[1]
            valor = int(partes[2])
            if conta in contas and contas[conta] >= valor:
                contas[conta] -= valor

        elif comando == 'TRANSFERIR':
            origem = partes[1]
            destino = partes[2]
            valor = int(partes[3])
            if origem in contas and destino in contas and contas[origem] >= valor:
                contas[origem] -= valor
                contas[destino] += valor

    return contas

def ratear_custo(pesos, total):
    if not pesos or total < 0:
        raise ValueError

    if total == 0:
        result = {}
        for nome in pesos:
            result[nome] = 0
        return result

    soma_pesos = sum(pesos.values())
    if soma_pesos == 0:
        raise ValueError

    if any(peso < 0 for peso in pesos.values()):
        raise ValueError

    # Passo 1: calcular parte inteira de cada nome
    partes_inteiras = {}
    for nome in pesos:
        peso = pesos[nome]
        if peso == 0:
            partes_inteiras[nome] = 0
        else:
            partes_inteiras[nome] = (total * peso) // soma_pesos

    # Soma das partes inteiras
    soma_partes = sum(partes_inteiras.values())

    # Sobra
    sobra = total - soma_partes

    # Passo 2: distribuir sobra
    restos = {}
    for nome in pesos:
        peso = pesos[nome]
        if peso == 0:
            restos[nome] = 0
        else:
            # Resto fracionario da divisao do passo 1
            restos[nome] = (total * peso) % soma_pesos

    # Distribuir sobra
    result = partes_inteiras.copy()
    sobra_distribuida = 0

    # Ordenar nomes por resto (decrescente), e em caso de empate, por nome alfabetico (crescente)
    # Para empate em resto, queremos o menor nome em ordem alfabetica
    nomes_ordenados = sorted(pesos.keys(), key=lambda x: (-restos[x], x))

    for nome in nomes_ordenados:
        peso = pesos[nome]
        if peso == 0:
            continue
        if sobra > 0:
            result[nome] += 1
            sobra -= 1
        else:
            break

    return result

def simular_esteira(n, comandos):
    posicao = 0
    mao = None
    esteira = [None] * n

    for comando in comandos:
        partes = comando.split()
        if partes[0] == 'POE':
            x = partes[1]
            if esteira[posicao] is not None:
                raise ValueError
            esteira[posicao] = x
        elif partes[0] == 'ANDA':
            k = int(partes[1])
            posicao = (posicao + k) % n
        elif partes[0] == 'GIRA':
            if posicao == 0:
                posicao = 0
            else:
                posicao = (posicao + 1) % n
        elif partes[0] == 'PEGA':
            if mao is not None:
                raise ValueError
            if esteira[posicao] is None:
                pass
            else:
                mao = esteira[posicao]
                esteira[posicao] = None
        elif partes[0] == 'SOLTA':
            if mao is None:
                raise ValueError
            if esteira[posicao] is None:
                pass
            else:
                # Procurar próxima posição livre no sentido atual
                posicao_atual = posicao
                found = False
                for i in range(n):
                    posicao_atual = (posicao_atual + 1) % n
                    if esteira[posicao_atual] is None:
                        esteira[posicao_atual] = mao
                        mao = None
                        found = True
                        break
                if not found:
                    raise ValueError
        else:
            raise ValueError

    return (posicao, mao, esteira)

